const ORDINARY_SPIRIT: &str = "Destroy target nonartifact attacking creature. It can't be regenerated. Create a black Spirit creature token. Its power is equal to that creature's power and its toughness is equal to that creature's toughness.";
const FULL_BROKEN: &str = "Destroy target nonartifact attacking creature. It can't be regenerated. Create a black Spirit creature token. Its power is equal to that creature's power and its toughness is equal to that creature's toughness. Sacrifice the token at the beginning of the next end step.";
const FULL_CIRCADIAN: &str = "Vivid — Seek X cards that each share a color with one or more permanents you control, where X is the number of colors among permanents you control. For each color among permanents you control, those cards perpetually gain \"This spell costs {1} less to cast.\"";
const FULL_WHITE_SUN: &str = "You gain X life. Create X 1/1 colorless Phyrexian Mite artifact creature tokens with toxic 1 and \"This token can't block.\" If X is 5 or more, destroy all other creatures. (Players dealt combat damage by a creature with toxic 1 also get a poison counter.)";
const WHITE_SUN_SEMANTIC: &str = "You gain X life. Create X 1/1 colorless Phyrexian Mite artifact creature tokens with toxic 1 and \"~ can't block.\" If X is 5 or more, destroy all other creatures.";
const FULL_BROOD: &str = "If you control an Eldrazi Spawn, create three 0/1 colorless Eldrazi Spawn creature tokens. They have \"Sacrifice this token: Add {C}.\" Otherwise, create one of those tokens.";
const NORMALIZED_BROOD: &str = "If you control an Eldrazi Spawn, create three 0/1 colorless Eldrazi Spawn creature tokens. They have \"Sacrifice ~: Add {C}.\" Otherwise, create one of those tokens.";
const CIRCADIAN_BODY: &str = "Seek X cards that each share a color with one or more permanents you control, where X is the number of colors among permanents you control. For each color among permanents you control, those cards perpetually gain \"This spell costs {1} less to cast.\"";
const CIRCADIAN_SEEK: &str = "Seek X cards that each share a color with one or more permanents you control, where X is the number of colors among permanents you control";
const CIRCADIAN_GRANT: &str = "For each color among permanents you control, those cards perpetually gain \"This spell costs {1} less to cast.\"";

#[test]
fn broken_visage_complete_public_chain() {
    let parsed = parse_oracle_text(FULL_BROKEN, "Broken Visage", &[], &["Instant".into()], &[]);
    assert_ordinary_spirit_shape(&parsed, 1);
    let chain = scope_chain(&parsed.abilities[0]);
    assert_eq!(
        chain.len(),
        3,
        "destroy, defined creation, independent cleanup"
    );
    assert!(matches!(
        *chain[0].effect,
        Effect::Destroy {
            cant_regenerate: true,
            ..
        }
    ));
    let Effect::Destroy {
        target: TargetFilter::Typed(target),
        ..
    } = chain[0].effect.as_ref()
    else {
        panic!("complete qualified target: {chain:#?}")
    };
    assert!(target.type_filters.contains(&TypeFilter::Creature));
    assert!(target
        .type_filters
        .contains(&TypeFilter::Non(Box::new(TypeFilter::Artifact))));
    assert!(target
        .properties
        .contains(&FilterProp::Attacking { defender: None }));
    assert!(matches!(*chain[1].effect, Effect::Token { .. }));
    let Effect::CreateDelayedTrigger {
        condition, effect, ..
    } = chain[2].effect.as_ref()
    else {
        panic!("normal delayed cleanup: {chain:#?}");
    };
    assert!(matches!(
        condition,
        DelayedTriggerCondition::AtNextPhase {
            phase: crate::types::phase::Phase::End
        }
    ));
    assert!(matches!(
        effect.effect.as_ref(),
        Effect::Sacrifice {
            target: TargetFilter::LastCreated,
            ..
        }
    ));
    assert_eq!(
        parsed.abilities[0].description.as_deref(),
        Some(FULL_BROKEN)
    );
}

fn scope_spell(text: &str) -> ParsedAbilities {
    parse_oracle_text(text, "Synthetic outer scope", &[], &["Instant".into()], &[])
}

fn scope_chain(def: &AbilityDefinition) -> Vec<&AbilityDefinition> {
    std::iter::successors(Some(def), |d| d.sub_ability.as_deref()).collect()
}

// SHAPE supplements the paid casts in integration::jev_spell_scope.
#[test]
fn numeric_gain_outer_ownership_preserves_complete_chains() {
    let feud = "You gain 10 life. Then if you have more life than an opponent, create a 5/5 white Giant Warrior creature token.";
    let pulse = "You gain 4 life. Then if an opponent has more life than you, return Pulse of the Fields to its owner's hand.";
    let survival = "You gain 2 life. Then if you have more life than an opponent, draw a card.\nRebound (If you cast this spell from your hand, exile it as it resolves. At the beginning of your next upkeep, you may cast this card from exile without paying its mana cost.)";
    for (name, text, amount, card_types) in [
        (
            "Feudkiller's Verdict",
            feud,
            10,
            vec!["Kindred".into(), "Sorcery".into()],
        ),
        ("Pulse of the Fields", pulse, 4, vec!["Instant".into()]),
        ("Survival Cache", survival, 2, vec!["Sorcery".into()]),
    ] {
        for prefix in ["", "Draw a card.\n"] {
            let source = format!("{prefix}{text}");
            let mut ir = parse_oracle_ir(&source, name, &[], &card_types, &[]);
            assert_eq!(ir.source_text, source);
            assert!(!ir.items.is_empty());
            assert!(ir
                .items
                .windows(2)
                .all(|pair| pair[0].source.span().first_line <= pair[1].source.span().first_line));
            let parsed = lower_oracle_ir(&mut ir);
            assert_eq!(parsed.abilities.len(), 1, "{source}: {parsed:#?}");
            assert!(parsed.statics.is_empty(), "{parsed:#?}");
            assert!(!has_unimplemented(&parsed.abilities[0]), "{parsed:#?}");
            let chain = scope_chain(&parsed.abilities[0]);
            let gain_index = usize::from(!prefix.is_empty());
            assert!(
                matches!(*chain[gain_index].effect, Effect::GainLife { amount: QuantityExpr::Fixed { value }, .. } if value == amount)
            );
            let conditional = chain[gain_index + 1];
            let (left, right) = if name == "Pulse of the Fields" {
                (
                    PlayerScope::Opponent {
                        aggregate: AggregateFunction::Max,
                    },
                    PlayerScope::Controller,
                )
            } else {
                (
                    PlayerScope::Controller,
                    PlayerScope::Opponent {
                        aggregate: AggregateFunction::Min,
                    },
                )
            };
            assert_eq!(
                conditional.condition,
                Some(AbilityCondition::QuantityCheck {
                    lhs: QuantityExpr::Ref {
                        qty: QuantityRef::LifeTotal { player: left }
                    },
                    comparator: crate::types::ability::Comparator::GT,
                    rhs: QuantityExpr::Ref {
                        qty: QuantityRef::LifeTotal { player: right }
                    },
                })
            );
            assert!(match name {
                "Feudkiller's Verdict" => matches!(*conditional.effect, Effect::Token { .. }),
                "Pulse of the Fields" => matches!(
                    *conditional.effect,
                    Effect::ChangeZone {
                        target: TargetFilter::SelfRef,
                        destination: Zone::Hand,
                        ..
                    }
                ),
                _ => matches!(*conditional.effect, Effect::Draw { .. }),
            });
            if name == "Survival Cache" {
                assert!(parsed.extracted_keywords.contains(&Keyword::Rebound));
            }
            let normalized = source.replace("Pulse of the Fields", "~");
            let expected_description = if name == "Survival Cache" {
                format!("{prefix}{}", survival.lines().next().unwrap())
            } else {
                normalized
            };
            assert_eq!(
                parsed.abilities[0].description.as_deref(),
                Some(expected_description.as_str())
            );
        }
    }
    // The full quoted-token body remains in both clients' positive population.
    for prefix in ["", "Draw a card.\n"] {
        assert_white_sun_shape(
            &scope_spell(&format!("{prefix}{FULL_WHITE_SUN}")),
            !prefix.is_empty(),
        );
    }
}

#[test]
fn noun_led_perpetual_then_preserves_whole_instruction() {
    let discover = "Seek three nonland cards, then nonland cards in your hand perpetually gain \"This spell costs {1} less to cast.\"";
    let teferi = "Counter target spell. Each card in its controller's graveyard, hand, and library with the same name as that spell perpetually gains \"This spell costs {2} more to cast.\"";
    for prefix in ["", "Draw a card.\n"] {
        let source = format!("{prefix}{discover}");
        let parsed = scope_spell(&source);
        assert_eq!(parsed.abilities.len(), 1, "{parsed:#?}");
        assert!(parsed.statics.is_empty());
        assert!(!has_unimplemented(&parsed.abilities[0]), "{parsed:#?}");
        let chain = scope_chain(&parsed.abilities[0]);
        let grant = chain
            .iter()
            .find(|node| matches!(*node.effect, Effect::ApplyPerpetual { .. }))
            .expect("complete all-hand grant");
        let Effect::ApplyPerpetual {
            target,
            modification,
        } = grant.effect.as_ref()
        else {
            unreachable!()
        };
        assert!(
            matches!(target, TargetFilter::Typed(filter) if filter.controller == Some(ControllerRef::You) && filter.type_filters.contains(&TypeFilter::Non(Box::new(TypeFilter::Land))) && filter.properties.contains(&FilterProp::InZone { zone: Zone::Hand })),
            "{target:#?}"
        );
        assert!(
            matches!(modification, crate::types::ability::PerpetualModification::ModifyCost { mode: crate::types::statics::CostModifyMode::Reduce, amount } if *amount == ManaCost::generic(1))
        );
        assert!(grant.reads_return_result.is_none());
        assert_eq!(
            parsed.abilities[0].description.as_deref(),
            Some(source.as_str())
        );
    }
    let parsed = parse_oracle_text(
        teferi,
        "Teferi's Contingency",
        &[],
        &["Instant".into()],
        &[],
    );
    let ir = parse_oracle_ir(
        teferi,
        "Teferi's Contingency",
        &[],
        &["Instant".into()],
        &[],
    );
    assert_eq!(ir.source_text, teferi);
    assert_eq!(ir.items.len(), 1);
    assert_eq!(ir.items[0].source.fragment(), Some(teferi));
    assert_eq!(parsed.abilities.len(), 1, "{parsed:#?}");
    let chain = scope_chain(&parsed.abilities[0]);
    assert!(matches!(*chain[0].effect, Effect::Counter { .. }));
    assert_eq!(
        chain.len(),
        2,
        "the entire unresolved subject is one instruction"
    );
    assert!(
        matches!(chain[1].effect.as_ref(), Effect::Unimplemented { description: Some(fragment), .. } if fragment == teferi.strip_prefix("Counter target spell. ").unwrap()),
        "{chain:#?}"
    );
    assert!(has_unimplemented(&parsed.abilities[0]));
    assert!(parsed.statics.is_empty());
    for text in [
        "You have no maximum hand size.",
        "You have no maximum hand size for the rest of the game.",
    ] {
        let complete = scope_spell(text);
        assert!(!has_unimplemented(&complete.abilities[0]), "{complete:#?}");
    }
    let bad_text =
        "You have no maximum hand size for the rest of the game with an unmodeled rider.";
    let bad = scope_spell(bad_text);
    assert!(bad.abilities.iter().any(has_unimplemented), "{bad:#?}");
    assert!(bad.statics.is_empty());
    assert!(bad.abilities.iter().flat_map(scope_chain).any(|node| matches!(node.effect.as_ref(), Effect::Unimplemented { description: Some(fragment), .. } if fragment.trim_end_matches('.') == bad_text.trim_end_matches('.'))), "{bad:#?}");
    for (name, text, types, abilities) in [
        ("Spellbook", "You have no maximum hand size.", "Artifact", 0),
        (
            "Reliquary Tower",
            "You have no maximum hand size.\n{T}: Add {C}.",
            "Land",
            1,
        ),
    ] {
        let hosted = parse_oracle_text(text, name, &[], &[types.into()], &[]);
        assert_eq!(hosted.abilities.len(), abilities, "{hosted:#?}");
        assert_eq!(hosted.statics.len(), 1);
        assert_eq!(hosted.statics[0].mode, StaticMode::NoMaximumHandSize);
        assert!(
            matches!(&hosted.statics[0].affected, Some(TargetFilter::Typed(filter)) if filter.controller == Some(ControllerRef::You))
        );
    }
}

fn assert_ordinary_spirit_shape(parsed: &ParsedAbilities, target_count: usize) {
    // SHAPE; actual creation is exercised in integration::jev_token_followup.
    assert_eq!(parsed.abilities.len(), 1, "{parsed:#?}");
    assert!(parsed.statics.is_empty());
    assert!(!has_unimplemented(&parsed.abilities[0]), "{parsed:#?}");
    assert!(parsed.parse_warnings.is_empty(), "{parsed:#?}");
    let chain = scope_chain(&parsed.abilities[0]);
    assert_eq!(
        chain
            .iter()
            .filter(
                |d| crate::types::ability::extract_target_filter_from_effect(&d.effect).is_some()
            )
            .count(),
        target_count
    );
    assert!(chain.iter().any(|d| matches!(
        *d.effect,
        Effect::Destroy {
            cant_regenerate: true,
            ..
        }
    )));
    let tokens: Vec<_> = chain
        .iter()
        .filter(|d| matches!(*d.effect, Effect::Token { .. }))
        .collect();
    assert_eq!(tokens.len(), 1);
    let token = tokens[0];
    assert_eq!(token.target_reads, TargetReadOrigin::ParentAnnouncement);
    let Effect::Token {
        power, toughness, ..
    } = token.effect.as_ref()
    else {
        unreachable!()
    };
    // CR 111.3 + CR 115.10a: the separate defining sentence adds no target.
    assert_eq!(
        *power,
        crate::types::ability::PtValue::Quantity(QuantityExpr::Ref {
            qty: QuantityRef::Power {
                scope: crate::types::ability::ObjectScope::Target
            }
        })
    );
    assert_eq!(
        *toughness,
        crate::types::ability::PtValue::Quantity(QuantityExpr::Ref {
            qty: QuantityRef::Toughness {
                scope: crate::types::ability::ObjectScope::Target
            }
        })
    );
}

#[test]
fn target_defined_token_ordinary_public_document() {
    let parsed = scope_spell(ORDINARY_SPIRIT);
    assert_ordinary_spirit_shape(&parsed, 1);
    assert_eq!(
        parsed.abilities[0].description.as_deref(),
        Some(ORDINARY_SPIRIT)
    );
}

#[test]
fn outer_spell_instruction_owns_nested_static_text() {
    // SHAPE: the complete outer spells own their nested definitions and grants.
    for (name, text) in [
        ("Broken Visage", FULL_BROKEN),
        ("Circadian Struggle", FULL_CIRCADIAN),
    ] {
        let mut ir = parse_oracle_ir(text, name, &[], &["Instant".into()], &[]);
        assert_eq!(ir.source_text, text);
        assert_eq!(ir.items.len(), 1, "{ir:#?}");
        assert_eq!(ir.items[0].source.fragment(), Some(text));
        let OracleNodeIr::Spell(body) = &ir.items[0].node else {
            panic!("outer spell owner: {ir:#?}")
        };
        if name == "Broken Visage" {
            assert_eq!(body.source_text, text);
            assert!(body
                .body
                .clauses
                .iter()
                .any(|c| matches!(c.parsed.effect, Effect::Destroy { .. })));
            let creator = body
                .body
                .clauses
                .iter()
                .find(|c| matches!(c.parsed.effect, Effect::Token { .. }))
                .expect("Spirit creator");
            assert!(body
                .body
                .clauses
                .iter()
                .any(|c| c.token_definition_owner == Some(creator.id)));
        } else {
            assert_eq!(body.source_text, CIRCADIAN_BODY);
        }
        let parsed = lower_oracle_ir(&mut ir);
        assert!(parsed.statics.is_empty(), "{name}: {parsed:#?}");
        assert_eq!(parsed.abilities.len(), 1);
        assert_eq!(parsed.abilities[0].description.as_deref(), Some(text));
        assert!(!has_unimplemented(&parsed.abilities[0]));
        let gaps: Vec<_> = scope_chain(&parsed.abilities[0])
            .iter()
            .filter_map(|d| match d.effect.as_ref() {
                Effect::Unimplemented { description, .. } => description.as_deref(),
                _ => None,
            })
            .collect();
        if name == "Broken Visage" {
            assert!(gaps.is_empty());
            assert!(scope_chain(&parsed.abilities[0])
                .iter()
                .any(|node| matches!(node.effect.as_ref(), Effect::CreateDelayedTrigger { .. })));
        } else {
            assert!(scope_chain(&parsed.abilities[0]).iter().any(|d| matches!(
                d.effect.as_ref(),
                Effect::Seek {
                    count: QuantityExpr::Ref {
                        qty: QuantityRef::DistinctColorsAmong { .. }
                    },
                    ..
                }
            )));
            assert!(gaps.is_empty());
            let seek = &parsed.abilities[0];
            let grant = seek.sub_ability.as_deref().expect("perpetual grant");
            assert!(seek.declares_return_result.is_some());
            assert_eq!(
                grant.reads_return_result.as_ref().map(|(id, _)| *id),
                seek.declares_return_result
            );
            assert!(matches!(
                grant.repeat_for,
                Some(QuantityExpr::Ref {
                    qty: QuantityRef::DistinctColorsAmong { .. }
                })
            ));
            assert!(
                matches!(grant.effect.as_ref(), Effect::ApplyPerpetual { modification: crate::types::ability::PerpetualModification::ModifyCost { mode: crate::types::statics::CostModifyMode::Reduce, amount }, .. } if *amount == crate::types::mana::ManaCost::generic(1))
            );
            assert!(parsed.parse_warnings.is_empty());
        }
    }
}

