/// CR 601.2c + CR 603.3d: a TARGETED "of their choice" whose filter is
/// controlled by the phase-trigger active player ("destroy target X that
/// player controls of their choice") routes target selection to that scoped
/// player. The parser stamps `target_chooser = Some(ScopedPlayer)` so the
/// trigger target-selection site can override the chooser away from the
/// source's controller (Magus of the Abyss / The Abyss deadlock). Tests the
/// `controller == ScopedPlayer` discriminator (the building block), not the
/// card name — any phase-trigger "that player controls of their choice"
/// target qualifies.
#[test]
fn scoped_player_of_their_choice_marks_target_chooser() {
    use crate::types::ability::TargetFilter;
    let r = parse(
            "At the beginning of each player's upkeep, destroy target nonartifact creature that player controls of their choice. It can't be regenerated.",
            "Magus of the Abyss",
            &[],
            &["Creature"],
            &["Human", "Wizard"],
        );
    // The phase trigger's effect lives in `trigger.execute`; the parser
    // stamps the chooser onto that lowered `AbilityDefinition`.
    assert!(
        r.triggers.iter().any(
            |t| t.execute.as_ref().and_then(|e| e.target_chooser.as_ref())
                == Some(&TargetFilter::ScopedPlayer)
        ),
        "expected a trigger whose execute.target_chooser == Some(ScopedPlayer); triggers: {:#?}",
        r.triggers
            .iter()
            .map(|t| t.execute.as_ref().map(|e| &e.target_chooser))
            .collect::<Vec<_>>(),
    );
}

/// CR 601.2c + CR 115.1: An announcing-player override belongs only to the
/// printed target phrase that carries it. Ordinary target phrases following
/// "of an opponent's choice" must return target choice to the controller.
#[test]
fn opponent_choice_chooser_does_not_leak_to_following_target_phrase() {
    let r = parse(
        "Destroy target nonbasic land you don't control and target nonbasic land of an opponent's choice you don't control. ~ deals 7 damage to target creature you don't control and 7 damage to target creature of an opponent's choice you don't control.",
        "Volcanic Offering",
        &[],
        &["Instant"],
        &[],
    );
    let mut choosers = Vec::new();
    let mut link = r.abilities.first();
    while let Some(ability) = link {
        choosers.push(ability.target_chooser.clone());
        link = ability.sub_ability.as_deref();
    }

    assert_eq!(
        choosers,
        vec![
            None,
            Some(TargetFilter::Opponent),
            None,
            Some(TargetFilter::Opponent),
        ],
        "only Volcanic Offering's two explicit opponent-choice targets may override the controller"
    );
}

