#[test]
fn leadership_vacuum_returns_target_players_commanders_to_command_zone() {
    let r = parse(
            "Target player returns each commander they control from the battlefield to the command zone.\nDraw a card.",
            "Leadership Vacuum",
            &[],
            &["Instant"],
            &[],
        );
    assert!(
        r.parse_warnings.is_empty(),
        "unexpected parse warnings: {:?}",
        r.parse_warnings
    );
    assert!(matches!(
        *r.abilities[0].effect,
        Effect::TargetOnly {
            target: TargetFilter::Player
        }
    ));
    let sub = r.abilities[0]
        .sub_ability
        .as_ref()
        .expect("expected target-player sub-ability");
    match &*sub.effect {
        Effect::ChangeZoneAll {
            origin,
            destination,
            target:
                TargetFilter::Typed(TypedFilter {
                    // CR 109.4 + CR 115.10a (issue #6505): "each commander THEY
                    // control" is the TARGET player's commanders, not the
                    // caster's. The subject "Target player" seeds the anaphoric
                    // "they" with the declared target player, and the
                    // resolution-pick leg rebinds that seed to `ScopedPlayer`
                    // (bound to the declared target player by the resolution-time
                    // `scoped_player` stamp), fixing the same class as Strategic
                    // Betrayal. Previously it wrongly resolved to `You` (the
                    // caster), contradicting this test's own name.
                    controller: Some(ControllerRef::ScopedPlayer),
                    properties,
                    ..
                }),
            ..
        } => {
            assert_eq!(*origin, None);
            assert_eq!(*destination, Zone::Command);
            assert!(properties.contains(&FilterProp::IsCommander));
        }
        other => panic!("expected command-zone ChangeZoneAll, got {other:?}"),
    }
}

