fn modal_spell_block_keeps_mode_branches_separate() {
    let r = parse(
        "Choose one —\n• Scry 1.\n• Draw a card.",
        "Test Charm",
        &[],
        &["Instant"],
        &[],
    );

    let modal = r.modal.expect("modal metadata should remain on spell face");
    assert_eq!(modal.mode_count, 2);
    assert_eq!(r.abilities.len(), 2);
    assert!(matches!(
        *r.abilities[0].effect,
        Effect::Scry {
            count: QuantityExpr::Fixed { value: 1 },
            ..
        }
    ));
    assert!(matches!(
        *r.abilities[1].effect,
        Effect::Draw {
            count: QuantityExpr::Fixed { value: 1 },
            ..
        }
    ));
}

/// Issue #5979 (modal-card context): "play up to <n> additional lands this
/// turn" also reaches the additional-land grammar as a modal mode bullet, not
/// only as a standalone sentence. Journey of Discovery's second mode ("You may
/// play up to two additional lands this turn.") must parse — through the
/// production card parser — to the `AdditionalLandDrop { count: 2 }` grant, not
/// misroute to `CastFromZone`. Entwine is a keyword line and adds no mode.
#[test]
fn journey_of_discovery_modal_up_to_two_additional_lands() {
    use crate::types::statics::StaticMode;
    let r = parse(
        "Choose one —\n• Search your library for up to two basic land cards, reveal them, put them into your hand, then shuffle.\n• You may play up to two additional lands this turn.\nEntwine {2}{G}",
        "Journey of Discovery",
        &[],
        &["Sorcery"],
        &[],
    );

    let modal = r.modal.expect("Journey of Discovery is a modal spell");
    assert_eq!(
        modal.mode_count, 2,
        "Entwine must not register as a third mode"
    );
    assert_eq!(
        r.abilities.len(),
        2,
        "one ability per mode: {:?}",
        r.abilities
    );

    // Second mode: the turn-scoped additional-land grant (count 2).
    match &*r.abilities[1].effect {
        Effect::GenericEffect {
            static_abilities, ..
        } => assert!(
            static_abilities
                .iter()
                .any(|d| d.mode == StaticMode::AdditionalLandDrop { count: 2 }),
            "expected AdditionalLandDrop {{ count: 2 }} in second mode, got {static_abilities:?}"
        ),
        other => {
            panic!("expected GenericEffect additional-land grant as second mode, got {other:?}")
        }
    }
}

/// Test that Entwine with a non-mana cost (Solar Tide) is parsed correctly.
/// Solar Tide: "Choose one —\n• Destroy all creatures with power 2 or less.\n• Destroy all creatures with power 3 or greater.\nEntwine—Sacrifice two lands."
#[test]
fn solar_tide_entwine_non_mana_cost() {
    let r = parse(
        "Choose one —\n• Destroy all creatures with power 2 or less.\n• Destroy all creatures with power 3 or greater.\nEntwine—Sacrifice two lands.",
        "Solar Tide",
        &[],
        &["Sorcery"],
        &[],
    );

    let modal = r.modal.expect("Solar Tide is a modal spell");
    assert_eq!(modal.mode_count, 2, "Solar Tide must have exactly 2 modes");
    // CR 702.42a: the em-dash cost is extracted as a non-mana Entwine keyword;
    // `synthesize_entwine` later copies it onto the ModalChoice.
    assert!(
        r.extracted_keywords.iter().any(|k| matches!(
            k,
            Keyword::Entwine(crate::types::keywords::EntwineCost::NonMana(
                AbilityCost::Sacrifice { .. }
            ))
        )),
        "expected non-mana Entwine keyword, got {:?}",
        r.extracted_keywords
    );

    assert_eq!(
        r.abilities.len(),
        2,
        "one ability per mode: {:?}",
        r.abilities
    );
}

